def plan(grid_size, starts, goals, obstacles, constraints) -> list:
    from collections import deque
    from heapq import heappush, heappop
    width, height = grid_size
    avoid_agent_collisions = constraints['avoid_agent_collisions']
    max_steps = constraints['max_steps']
    movement = constraints['movement']

    def is_valid(pos):
        x, y = pos
        return 0 <= x < width and 0 <= y < height and (pos not in obstacles_set)

    def get_neighbors(pos):
        x, y = pos
        neighbors = []
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = (x + dx, y + dy)
            neighbor = (nx, ny)
            if is_valid(neighbor):
                neighbors.append(neighbor)
        return neighbors

    def a_star(start, goal):
        open_set = []
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}
        heappush(open_set, (f_score[start], start))
        while open_set:
            _, current = heappop(open_set)
            if current == goal:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.append(start)
                path.reverse()
                return path
            for neighbor in get_neighbors(current):
                tentative_g_score = g_score[current] + 1
                if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g_score
                    f_score[neighbor] = g_score[neighbor] + heuristic(neighbor, goal)
                    if neighbor not in [i[1] for i in open_set]:
                        heappush(open_set, (f_score[neighbor], neighbor))
        return None

    def heuristic(a, b):
        ax, ay = a
        bx, by = b
        return abs(ax - bx) + abs(ay - by)

    def solve(starts, goals):
        paths = []
        for start, goal in zip(starts, goals):
            path = a_star(start, goal)
            if path:
                paths.append(path)
            else:
                return None
        return paths
    obstacles_set = set(obstacles)
    paths = solve(starts, goals)
    if paths is None:
        return []
    return paths
